[CmdletBinding()]
param(
 [ValidateSet('Local','VmCreateKill','VmRecoverShutdown','VmOfflineCompact','VmNegative','Final','PowerCut')][string]$Tier='Local',
 [ValidateSet('Debug','Release')][string]$Configuration='Release',
 [string]$Executable='',[string]$HostArtifact='',[string]$Bundle='',[string]$DriveLetter='',[string]$StateFile='',[string]$EvidenceDirectory='',[ValidatePattern('^$|^[0-9A-Fa-f]{40}$')][string]$ExpectedSourceCommit='',[switch]$SafetyAcknowledged
)
$ErrorActionPreference='Stop'; Set-StrictMode -Version Latest
$root=Split-Path -Parent $PSScriptRoot
function Block($m){Write-Output "BLOCKED_VM_NO_APPROVED_TARGET: $m";exit 77}
function Need($v,$m){if(-not $v){throw $m}}
function J($x){$x|ConvertTo-Json -Depth 16 -Compress}
function Stable($x){J ([ordered]@{stable_identities=@($x.stable_identities);aim_stable=@($x.aim_stable);physical_devices=@($x.physical_devices);drive_mappings=@($x.drive_mappings)})}
function Read-Evidence($p){$r=Get-Content -LiteralPath $p -Raw -Encoding UTF8;Need($r-notmatch'(?i)(password|private[ _-]?key|secret|token)') 'Evidence contains a prohibited secret term.';$r|ConvertFrom-Json}
function Must($x,$p,$m){Need($null-ne$x.$p)$m;return $x.$p}
function Resolve-ExpectedCommit {
 param([string]$Explicit)
 if(-not [string]::IsNullOrEmpty($Explicit)){ return $Explicit.ToLowerInvariant() }
 $old=$ErrorActionPreference;try{$ErrorActionPreference='Continue';$output=@(& git.exe -C $root rev-parse HEAD 2>$null);$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 Need($code-eq0-and$output.Count-eq1-and([string]$output[0])-cmatch'^[0-9a-f]{40}$') 'Unable to resolve repository HEAD commit.'
 return ([string]$output[0]).ToLowerInvariant()
}
function Exact($x,[string[]]$names,[string]$message){Need((@($x.PSObject.Properties.Name)-join'|')-ceq($names-join'|'))$message}
function Utc($x,[string]$message){[datetimeoffset]$v=[datetimeoffset]::MinValue;Need($x-is[string]-and$x-cmatch'^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,7})?Z$'-and[datetimeoffset]::TryParse($x,[globalization.cultureinfo]::InvariantCulture,[globalization.datetimestyles]::RoundtripKind,[ref]$v))$message;return $v}
function StringArray($x,[string]$message){Need($x-is[array]-and@($x|?{$_-isnot[string]}).Count-eq0)$message}
function StrictJson($path){$bytes=[IO.File]::ReadAllBytes($path);Need($bytes.Length-ge4-and-not($bytes[0]-eq239-and$bytes[1]-eq187-and$bytes[2]-eq191))'PowerCut evidence must be UTF-8 without BOM.';try{$text=[text.utf8encoding]::new($false,$true).GetString($bytes)}catch{throw 'PowerCut evidence is not valid UTF-8.'};Need($text.EndsWith("`r`n")-and$text.Length-gt2)'PowerCut evidence must have CRLF EOF.';$body=$text.Substring(0,$text.Length-2);Need($body-notmatch'[\r\n]')'PowerCut evidence must be single-line JSON.';try{$doc=$body|ConvertFrom-Json}catch{throw 'PowerCut evidence JSON is invalid.'};Need($body-ceq($doc|ConvertTo-Json -Compress -Depth 20))'PowerCut evidence is not canonical JSON.';return $doc}
function Assert-PowerInventory($x,[string]$message){Exact $x @('stable_identities','drive_mappings') $message;StringArray $x.stable_identities $message;StringArray $x.drive_mappings $message}
function Assert-PowerVolume($x,[string]$message){Exact $x @('volume_guid','filesystem','partition_style','disk_number','partition_number','expected_physical_identity','validated_expected') $message;Need($x.volume_guid-is[string]-and$x.volume_guid.Length-gt0-and$x.filesystem-ceq'NTFS'-and$x.partition_style-ceq'GPT'-and(($x.disk_number-is[int])-or($x.disk_number-is[long]))-and$x.disk_number-ge0-and(($x.partition_number-is[int])-or($x.partition_number-is[long]))-and$x.partition_number-gt0-and$x.expected_physical_identity-is[string]-and$x.expected_physical_identity.Length-gt0-and$x.validated_expected-is[bool]-and$x.validated_expected)$message}
function Verify-PowerCut($dir,[string]$hostArtifact,[string]$commit){
 $dir=[IO.Path]::GetFullPath($dir);Need([io.directory]::Exists($dir))'PowerCut requires an absolute existing EvidenceDirectory.';Need((@(Get-ChildItem -LiteralPath $dir -Force|% Name)|Sort-Object)-join'|' -ceq'myrd.m4.live-powercut.v1.json')'PowerCut evidence inventory is invalid.'
 Need(-not[string]::IsNullOrWhiteSpace($hostArtifact)-and[io.file]::Exists($hostArtifact))'PowerCut requires the exact existing host-built artifact.';$hostArtifact=[io.path]::GetFullPath($hostArtifact);Need($hostArtifact-match'(?i)\\Release\\myrd\.exe$')'Host artifact must be Release myrd.exe.';$d=StrictJson (Join-Path $dir 'myrd.m4.live-powercut.v1.json')
 Exact $d @('schema','status','source_commit','executable_sha256','armed_boot_utc','recovered_boot_utc','shutdown_events','old_pid','old_pid_absent','armed_generation','recovered_generation','baseline_inventory','inventory_after','volume','hashes_before','hashes_after','bundle_inventory_before','bundle_inventory_after','graceful_exit') 'PowerCut evidence schema is invalid.'
 Need($d.schema-ceq'myrd.m4.live-powercut.v1'-and$d.status-ceq'PASS'-and$d.source_commit-ceq$commit-and$d.executable_sha256-ceq(Get-FileHash -LiteralPath $hostArtifact -Algorithm SHA256).Hash.ToUpperInvariant())'PowerCut source/artifact identity is invalid.'
 $armed=Utc $d.armed_boot_utc 'PowerCut armed boot UTC is invalid.';$recovered=Utc $d.recovered_boot_utc 'PowerCut recovered boot UTC is invalid.';Need($recovered-gt$armed)'PowerCut boot did not advance.'
 Need($d.shutdown_events-is[array]-and@($d.shutdown_events).Count-gt0)'PowerCut shutdown event set is invalid.';$ids=@();foreach($e in @($d.shutdown_events)){Exact $e @('id','time_utc') 'PowerCut shutdown event schema is invalid.';Need((($e.id-is[int])-or($e.id-is[long]))-and$e.id-in@(41,6008))'PowerCut shutdown event type is invalid.';$t=Utc $e.time_utc 'PowerCut shutdown event UTC is invalid.';Need($t-gt$armed-and$t-le$recovered)'PowerCut shutdown event window is invalid.';$ids+=$e.id};Need(@($ids|Where-Object{$_-eq41}).Count-gt0-and@($ids|Where-Object{$_-eq6008}).Count-gt0)'PowerCut shutdown event IDs are invalid.'
 Need((($d.old_pid-is[int])-or($d.old_pid-is[long]))-and$d.old_pid-gt0-and$d.old_pid_absent-is[bool]-and$d.old_pid_absent-and(($d.graceful_exit-is[int])-or($d.graceful_exit-is[long]))-and$d.graceful_exit-eq0)'PowerCut PID/exit evidence is invalid.';Need((($d.armed_generation-is[int])-or($d.armed_generation-is[long]))-and(($d.recovered_generation-is[int])-or($d.recovered_generation-is[long]))-and$d.armed_generation-gt0-and$d.recovered_generation-gt$d.armed_generation)'PowerCut generations are invalid.'
 Assert-PowerInventory $d.baseline_inventory 'PowerCut baseline inventory is invalid.';Assert-PowerInventory $d.inventory_after 'PowerCut post inventory is invalid.';Need(($d.baseline_inventory|ConvertTo-Json -Compress)-ceq($d.inventory_after|ConvertTo-Json -Compress))'PowerCut inventory is not clean.';Assert-PowerVolume $d.volume 'PowerCut volume evidence is invalid.'
 foreach($h in @($d.hashes_before,$d.hashes_after)){Need($null-ne$h)'PowerCut hashes are invalid.'};Exact $d.hashes_before @('A.txt','D.txt') 'PowerCut pre-hash schema is invalid.';Exact $d.hashes_after @('A.txt','D.txt','post-recovery.txt') 'PowerCut post-hash schema is invalid.';foreach($name in @('A.txt','D.txt')){Need($d.hashes_before.$name-is[string]-and$d.hashes_before.$name-cmatch'^[0-9A-F]{64}$'-and$d.hashes_after.$name-is[string]-and$d.hashes_after.$name-cmatch'^[0-9A-F]{64}$'-and$d.hashes_before.$name-ceq$d.hashes_after.$name)'PowerCut workload hashes are invalid.'};Need($d.hashes_after.'post-recovery.txt'-is[string]-and$d.hashes_after.'post-recovery.txt'-cmatch'^[0-9A-F]{64}$')'PowerCut post-recovery hash is invalid.'
 StringArray $d.bundle_inventory_before 'PowerCut pre bundle inventory is invalid.';StringArray $d.bundle_inventory_after 'PowerCut post bundle inventory is invalid.';Need((@($d.bundle_inventory_before)-join"`n")-ceq(@($d.bundle_inventory_after)-join"`n"))'PowerCut bundle inventory changed.';Write-Output "M4 PowerCut PASS: same-commit evidence for $commit"
}
function Check-Negative($n,$case,$commit,$base,$identity,$rootPath){
 Need($n.schema-eq'myrd.m4.negative-case.v1'-and$n.case-eq$case-and$n.status-eq'PASS') "Invalid negative schema/status: $case"
 Need($n.source_commit-eq$commit-and$n.executable_path-eq$identity.executable_path-and$n.executable_sha256-eq$identity.executable_sha256-and$n.bundle_root-eq$rootPath) "Negative identity mismatch: $case"
 Need($n.process.pid-gt0-and$n.process.started_utc-and$n.process.ended_utc-and$n.process.timeout_seconds-gt0) "Negative process evidence missing: $case"
 $target=$(if($case-eq'compact_lock'){[string]$n.argv[2]}else{[string]$n.argv[2]});$target=[IO.Path]::GetFullPath($target);Need($target.StartsWith($rootPath+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) "Negative target escaped derived root: $case"
 if($case-eq'compact_lock'){Need(@($n.argv).Count-eq3-and$n.argv[0]-eq'compact'-and$n.argv[1]-eq'--bundle') 'compact_lock target argv invalid'}else{Need(@($n.argv).Count-eq13-and$n.argv[0]-eq'run'-and$n.argv[1]-eq'--bundle'-and$n.argv[3]-eq'--size'-and$n.argv[4]-in@('64M','128M')-and$n.argv[5]-eq'--drive-letter'-and$n.argv[7]-eq'--checkpoint-seconds'-and$n.argv[8]-in@('5','86400')-and$n.argv[9]-eq'--checkpoint-dirty-mb'-and$n.argv[10]-in@('1','1048576')-and$n.argv[11]-eq'--ram-limit'-and$n.argv[12]-eq'64M') "Negative run argv invalid: $case"}
 $errorPattern=@{unknown_nonempty='classify_bundle: non-empty bundle has no disk\.rdm';size_mismatch='validate_recovered_image: requested size does not match recovered bundle geometry';occupied_letter='preflight_drive_letter: requested drive letter is occupied';gen0='Error: incomplete generation-zero bundle at ';writer_lock='another process owns the manifest writer lock';missing_driver='discover_aim_adapter: no AIM adapter found';busy_volume='Close applications using the RAM disk and press Ctrl\+C again\.';compact_lock='Error: bundle is in use\.'}[$case];Need([string]$n.process.stderr-match$errorPattern) "Negative refusal output mismatch: $case"
 if($case-ne'busy_volume'){Need([int]$n.process.exit-eq1) "Negative refusal exit missing: $case"}else{Need([int]$n.process.exit-eq0) 'busy holder did not exit cleanly'}
 if($case-notin@('writer_lock','busy_volume','compact_lock')){Need((Stable $n.oracle.before.inventory)-eq$base-and(Stable $n.oracle.after.inventory)-eq$base) "Negative inventory mutation: $case"}else{Need((Stable $n.oracle.after.inventory)-eq$base) "Negative cleanup baseline missing: $case"}
 Need($n.expected_refusal-and$n.oracle.before-and$n.oracle.after) "Negative oracle missing: $case"
 switch($case){
  'unknown_nonempty'{Need($n.expected_refusal-eq'unknown_nonempty'-and$n.oracle.before.bundle_hash-eq$n.oracle.after.bundle_hash-and$n.oracle.before.marker_hash-eq$n.oracle.after.marker_hash) 'unknown_nonempty oracle invalid'}
  'size_mismatch'{Need($n.expected_refusal-eq'size_mismatch'-and$n.oracle.before.bundle_hash-eq$n.oracle.after.bundle_hash) 'size_mismatch oracle invalid'}
  'occupied_letter'{Need($n.expected_refusal-eq'occupied_letter'-and$n.oracle.before.letter_guid-eq$n.oracle.after.letter_guid-and$n.oracle.after.bundle_absent) 'occupied_letter oracle invalid'}
  'gen0'{Need($n.expected_refusal-eq'generation_zero'-and$n.oracle.before.fixture_hashes-eq$n.oracle.after.fixture_hashes) 'gen0 oracle invalid'}
  'writer_lock'{Need($n.expected_refusal-eq'writer_lock'-and$n.oracle.before.refusal_bundle_hash-eq$n.oracle.after.refusal_bundle_hash-and$n.oracle.after.first_exit-eq0) 'writer_lock oracle invalid'}
  'missing_driver'{Need($n.expected_refusal-eq'missing_driver'-and$n.oracle.before.driver_absent-and$n.oracle.after.windows_unchanged) 'missing_driver oracle invalid'}
  'busy_volume'{Need($n.expected_refusal-eq'busy_volume'-and$n.oracle.after.first_alive_after_break-and$n.oracle.after.busy_guidance_observed-and$n.oracle.after.second_exit-eq0-and$n.oracle.after.baseline_restored) 'busy_volume oracle invalid'}
  'compact_lock'{Need($n.expected_refusal-eq'compact_in_use'-and$n.oracle.before.refusal_bundle_hash-eq$n.oracle.after.refusal_bundle_hash-and$n.oracle.after.first_exit-eq0) 'compact_lock oracle invalid'}
 }
}
function Verify-Final($dir,[string]$hostArtifact,[string]$expectedCommit=''){
 $dir=[IO.Path]::GetFullPath($dir);Need([IO.Directory]::Exists($dir))'Final requires an absolute existing EvidenceDirectory.'
 $names=@('CreateKill','RecoverShutdown','OfflineCompact','Negative');$states=@();foreach($name in $names){$p=Join-Path $dir "m4-lifecycle-$name.v1.json";Need([IO.File]::Exists($p))"Missing phase evidence: $name";$states+=Read-Evidence $p}
 $commit=Resolve-ExpectedCommit $expectedCommit;$a=$states[0]
 Need(-not[string]::IsNullOrWhiteSpace($hostArtifact)-and[IO.File]::Exists($hostArtifact))'Final requires the exact existing host-built artifact.';$hostArtifact=[IO.Path]::GetFullPath($hostArtifact);Need($hostArtifact-match'(?i)\\Release\\myrd\.exe$')'Host artifact must be Release myrd.exe.';Need((Get-FileHash -LiteralPath $hostArtifact -Algorithm SHA256).Hash-eq$a.executable_sha256)'Host and VM executable SHA-256 differ.'
 foreach($s in $states){Need($s.schema-eq'myrd.m4.lifecycle.v1'-and$s.phase-in$names-and$s.source_commit-eq$commit) 'Phase schema/name/commit mismatch.';Need($s.executable_path-eq$a.executable_path-and$s.executable_sha256-eq$a.executable_sha256-and$s.executable_sha256-match'^[0-9A-Fa-f]{64}$'-and$s.bundle_path-eq$a.bundle_path-and$s.drive_letter-eq$a.drive_letter-and(J $s.argv)-eq(J $a.argv)-and(J $s.constants)-eq(J $a.constants)) 'Phase executable or frozen identity mismatch.';Need((Stable $s.baseline_inventory)-eq(Stable $a.baseline_inventory)) 'Stable baseline mismatch.'}
 Need((J @($states|% phase))-eq(J $names))'Phase ordering mismatch.';Need(@($a.argv).Count-eq13-and$a.constants.size-eq'64M'-and[int]$a.constants.checkpoint_seconds-eq5-and[int]$a.constants.checkpoint_dirty_mb-eq1-and$a.constants.ram_limit-eq'64M')'Frozen argv/constants mismatch.'
 Need($a.status-eq'REBOOT_REQUIRED_EXPECTED'-and$a.pid-gt0-and$a.kill.pid-eq$a.pid-and$a.kill.killed-and$a.kill.exit-ne259-and$a.checkpoint_observed.generation-gt$a.ready_observed.generation-and$a.generation-eq$a.checkpoint_observed.generation-and$a.ready_observed.generation-gt0-and$a.ready_observed.filesystem-eq'NTFS'-and$a.ready_observed.partition_style-eq'GPT'-and$a.ready_observed.disk_number-ge0-and$a.ready_observed.partition_number-gt0-and$a.ready_observed.volume_guid-ne'ABSENT')'Create GPT/NTFS ready/kill/checkpoint successor evidence invalid.';Need(@($a.inventory_after.aim_stable).Count-gt@($a.baseline_inventory.aim_stable).Count)'Create AIM delta missing.'
 $baseStable=Stable $a.baseline_inventory;$r=$states[1];$recoverStable=Stable $r.inventory_after;Need([datetime]$r.boot_identity-gt[datetime]$a.boot_identity)'Recovery did not follow a newer Windows boot.';Need($recoverStable-eq$baseStable)'Recovery stable baseline mismatch.';Need($r.status-eq'PASS'-and$r.exit_codes.run-eq0-and$r.shutdown_stdout_boundary-ge0)'Recovery status/exit/boundary invalid.';Need($r.final_checkpoint_observed.generation-eq$r.generation-and$r.final_checkpoint_observed.generation-gt$r.checkpoint_observed.generation-and$r.final_checkpoint_observed.line-eq"Checkpoint committed generation $($r.generation).")'Recovery Ctrl+C checkpoint invalid.';Need($r.recovery_audit.schema-eq'myrd.m4.recovery-process-audit.v1'-and$r.recovery_audit.subscription-and$r.recovery_audit.subscribed_utc-and$r.recovery_audit.myrd_pid-gt0-and$r.recovery_audit.started_utc-and$r.recovery_audit.ended_utc-and$r.recovery_audit.quiescence_milliseconds-ge300-and[datetime]$r.recovery_audit.subscribed_utc-le[datetime]$r.recovery_audit.started_utc-and[datetime]$r.recovery_audit.started_utc-le[datetime]$r.recovery_audit.ended_utc)'Recovery audit envelope invalid.';Need(@($r.recovery_audit.children|?{[string]::IsNullOrWhiteSpace([string]$_.command_line)-or$_.name-match'(?i)(powershell|provision|initialize-disk)' -or $_.command_line-match'(?i)(provision_volume|Initialize-Disk|New-Partition|Format-Volume)'}).Count-eq0)'Recovery provisioning descendant or unavailable command line detected.';Need($r.hashes.'A.txt'-match'^[0-9A-Fa-f]{64}$'-and$r.hashes.'D.txt'-match'^[0-9A-Fa-f]{64}$'-and$r.hashes.'A.txt'-eq$a.hashes.'A.txt')'Recovery workload hashes invalid.'
 $o=$states[2];$offlineStable=Stable $o.inventory_after;Need($o.status-eq'PASS'-and($offlineStable-eq$baseStable)-and$o.compact_process.argv[0]-eq'compact'-and$o.compact_process.argv[1]-eq'--bundle'-and$o.compact_process.argv[2]-eq$a.bundle_path-and$o.compact_process.exit-eq0-and$o.compact_process.stdout-match'(?m)^Compacted bundle to generation [1-9][0-9]*\.$'-and[uint64]$o.compact_observed_generation-eq([uint64]$r.generation+1)-and[uint64]$o.third_ready_generation-eq[uint64]$o.compact_observed_generation-and$o.exit_codes.third_run-eq0-and$o.hashes.'A.txt'-eq$r.hashes.'A.txt'-and$o.hashes.'D.txt'-eq$r.hashes.'D.txt')'Offline compact/third-run evidence invalid.'
 $cases=@('unknown_nonempty','size_mismatch','occupied_letter','gen0','writer_lock','missing_driver','busy_volume','compact_lock');$seen=@();foreach($c in $cases){$p=Join-Path $dir "m4-negative-$c.v1.json";Need([IO.File]::Exists($p))"Missing negative evidence: $c";$n=Read-Evidence $p;Check-Negative $n $c $commit $baseStable $a "$($a.bundle_path).r7-negative";$seen+=$n.case};$neg=$states[3];$negativeStable=Stable $neg.inventory_after;Need($negativeStable-eq$baseStable)'Negative aggregate stable inventory mismatch.';Need($neg.status-eq'PASS'-and(J @($neg.negative_cases))-eq(J $cases)-and@($seen|Select-Object -Unique).Count-eq8)'Negative aggregate invalid.'
 Write-Output "M4 Final PASS: same-commit lifecycle evidence for $commit"
}
function SelfTest {
 $d=Join-Path ([IO.Path]::GetTempPath())('m4-final-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $d|Out-Null
 try {
  $commit=((& git.exe -C $root rev-parse HEAD)-join '').Trim();$inv=[ordered]@{boot_identity='2026-01-01T00:00:00Z';stable_identities=@('disk|1');aim_stable=@();physical_devices=@('\\.\PhysicalDrive0|disk|1');drive_mappings=@('C:|volume-c|0:1')}
  $id=[ordered]@{schema='myrd.m4.lifecycle.v1';source_commit=$commit;executable_path='C:\approved\Release\myrd.exe';executable_sha256=('a'*64);bundle_path='C:\approved\bundle';drive_letter='R';argv=@('run','--bundle','C:\approved\bundle','--size','64M','--drive-letter','R:','--checkpoint-seconds','5','--checkpoint-dirty-mb','1','--ram-limit','64M');constants=[ordered]@{size='64M';checkpoint_seconds=5;checkpoint_dirty_mb=1;ram_limit='64M'};baseline_inventory=$inv;hashes=[ordered]@{'A.txt'='A';'D.txt'='D'}}
  function Copy-Object($x){(J $x)|ConvertFrom-Json}
  $c=Copy-Object $id;$c|Add-Member phase CreateKill;$c|Add-Member boot_identity '2026-01-01T00:00:00Z';$c|Add-Member inventory_after ([ordered]@{boot_identity='2026-01-01T00:00:00Z';stable_identities=@('disk|1','aim|1');aim_stable=@('aim|1');physical_devices=@('\\.\PhysicalDrive0|disk|1','\\.\PhysicalDrive9|aim|1');drive_mappings=@('C:|volume-c|0:1','R:|volume-r|9:1')});$c|Add-Member ready_observed ([ordered]@{generation=1;volume_guid='\\?\Volume{11111111-1111-1111-1111-111111111111}\';filesystem='NTFS';partition_style='GPT';disk_number=9;partition_number=1});$c|Add-Member status REBOOT_REQUIRED_EXPECTED;$c|Add-Member pid 42;$c|Add-Member kill ([ordered]@{pid=42;killed=$true;exit=1});$c|Add-Member checkpoint_observed ([ordered]@{generation=2});$c|Add-Member generation 2
  $r=Copy-Object $id;$r|Add-Member phase RecoverShutdown;$r|Add-Member boot_identity '2026-01-01T00:01:00Z';$r|Add-Member status PASS;$r|Add-Member inventory_after $inv;$r|Add-Member generation 3;$r|Add-Member checkpoint_observed ([ordered]@{generation=2;line='Checkpoint committed generation 2.'});$r|Add-Member shutdown_stdout_boundary 10;$r|Add-Member final_checkpoint_observed ([ordered]@{generation=3;line='Checkpoint committed generation 3.'});$r.hashes.'A.txt'='a'*64;$r.hashes.'D.txt'='d'*64;$r|Add-Member exit_codes ([ordered]@{run=0});$r|Add-Member recovery_audit ([ordered]@{schema='myrd.m4.recovery-process-audit.v1';subscription='selftest';subscribed_utc='2025-12-31T23:59:59Z';myrd_pid=43;started_utc='2026-01-01T00:00:00Z';ended_utc='2026-01-01T00:00:01Z';quiescence_milliseconds=300;children=@()});$c.hashes.'A.txt'='a'*64
  $o=Copy-Object $id;$o|Add-Member phase OfflineCompact;$o|Add-Member status PASS;$o|Add-Member inventory_after $inv;$o|Add-Member generation 4;$o|Add-Member compact_observed_generation 4;$o|Add-Member third_ready_generation 4;$o.hashes.'A.txt'='a'*64;$o.hashes.'D.txt'='d'*64;$o|Add-Member exit_codes ([ordered]@{third_run=0});$o|Add-Member compact_process ([ordered]@{argv=@('compact','--bundle',$id.bundle_path);exit=0;stdout='Compacted bundle to generation 4.'})
  $n=Copy-Object $id;$n|Add-Member phase Negative;$n|Add-Member status PASS;$n|Add-Member inventory_after $inv;$n|Add-Member negative_cases @('unknown_nonempty','size_mismatch','occupied_letter','gen0','writer_lock','missing_driver','busy_volume','compact_lock')
  @($c,$r,$o,$n)|%{[IO.File]::WriteAllText((Join-Path $d "m4-lifecycle-$($_.phase).v1.json"),(J $_),[Text.UTF8Encoding]::new($false))}
